import{_ as o,l as r,o as e,c as l,v as i,p,x as t,d as s,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"通胀目标制","description":"","frontmatter":{"title":"通胀目标制","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/inflation-targeting.md","filePath":"econ/inflation-targeting.md","lastUpdated":1789023840000}'),h={name:"econ/inflation-targeting.md"};function c(T,a,m,B,_,I){const n=r("Mermaid");return e(),l("div",null,[a[1]||(a[1]=i('<h1 id="通胀目标制" tabindex="-1">通胀目标制 <a class="header-anchor" href="#通胀目标制" aria-label="Permalink to &quot;通胀目标制&quot;">​</a></h1><div class="epigraph"><p>把 $\\pi^*$ 写成公开的名义锚，并在中期钉住它；短期仍可权衡缺口——灵活目标制是最优目标规则的制度外壳，不是每季把通胀钉死。</p><footer>—— Svensson 的通胀目标制与预测目标；Bernanke 对 IT 作为框架的论述</footer></div><p><a href="/econ/optimal-nk-policy">上一课</a>给出二次损失下的目标制一阶条件：承诺把 \\(\\pi\\) 与 \\(\\tilde{y}\\) 锁在一条规则里。本课的缺口是制度：如何把这条规则说成公众能形成预期的框架。Svensson 把通胀目标制（IT）写成损失函数加预测目标；Bernanke 强调沟通与责任。走廊与准备金利息下一课才问 \\(i\\) 如何在银行体系里实现。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>最优条件不能当新闻稿。需要一个可观测的锚 \\(\\pi^*\\)、一个中期地平，以及是否允许短期偏离。严格 IT：每期把预期通胀钉在 \\(\\pi^*\\)，巧合成立时这就是最优。灵活 IT：损失里仍有缺口，预测路径可以暂时离开 \\(\\pi^*\\)，但承诺回到它。缺口不是再推 Ramsey，而是：公开 \\(\\pi^*\\) 如何把泰勒原理与承诺语言操作化，避免「看情况」的卢卡斯批判。</p><p><span class="marginnote">点目标与区间是沟通技术。理论对象是 \\(\\pi^*\\) 与损失权重，不是 1% 带宽是否印在公报上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Svensson：央行最小化与 Woodford 同族的损失，工具是利率路径，中间目标常是通胀预测——预测目标制。公布预测，等于把目标制规则的前瞻部分交给公众检验。Bernanke：IT 是受约束的权变框架——有锚，但不是机械的货币数量规则。与泰勒规则的关系：IT 是目标，泰勒是一种工具规则；可以在 IT 下用泰勒型反应，系数仍要满足确定性。</p>',8)),(e(),p(E,null,{default:t(()=>[d(n,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20OPT%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%E7%9B%AE%E6%A0%87%E5%88%B6%E4%B8%80%E9%98%B6%E6%9D%A1%E4%BB%B6%22%5D%20--%3E%20IT%5B%22%E5%85%AC%E5%BC%80%20%CF%80*%20%E4%B8%8E%E4%B8%AD%E6%9C%9F%E9%94%9A%22%5D%0A%20%20IT%20--%3E%20FLEX%5B%22%E7%81%B5%E6%B4%BB%EF%BC%9A%E7%9F%AD%E6%9C%9F%E6%9D%83%E8%A1%A1%22%5D%0A%20%20IT%20--%3E%20COMM%5B%22%E9%A2%84%E6%B5%8B%E4%B8%8E%E6%B2%9F%E9%80%9A%22%5D%0A%20%20COMM%20--%3E%20EXP%5B%22E%CF%80%20%E8%A2%AB%E9%94%9A%E4%BD%8F%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<p>平均通胀目标、价格水平目标是 IT 的堂兄弟：把过去的偏离记入未来，更接近承诺的历史依赖。下限上它们特别有用——非常规课已经用过。本课在正利率区把 IT 钉成默认名义锚。</p><h3 id="不是货币数量目标复辟" tabindex="-1">不是货币数量目标复辟 <a class="header-anchor" href="#不是货币数量目标复辟" aria-label="Permalink to &quot;不是货币数量目标复辟&quot;">​</a></h3><p>Friedman 的 \\(k\\) 百分是工具规则盯 \\(M\\)。IT 盯的是 \\(\\pi\\) 结果， \\(M\\) 内生。数量方程仍给长期 \\(P\\) 的会计；操作上现代央行不靠外生 \\(M\\) 路径。把 IT 写成「不再相信货币」，会取消长期中性。</p><h3 id="沟通不是把-ramsey-一阶条件念出来" tabindex="-1">沟通不是把 Ramsey 一阶条件念出来 <a class="header-anchor" href="#沟通不是把-ramsey-一阶条件念出来" aria-label="Permalink to &quot;沟通不是把 Ramsey 一阶条件念出来&quot;">​</a></h3><p>公众需要的是 \\(\\pi^*\\)、地平与「暂时偏离如何回来」。把目标制规则的系数逐季公布，并不自动等于承诺：权变也可以拟合出相似的反应。</p><p>责任与任期用来补这一点。本课把 IT 当框架，不把某次新闻发布会当识别。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>公众看见 \\(\\pi^*\\) 与反应函数， \\(\\mathbb{E}\\pi_{t+1}\\) 进入 NKPC 与 IS。成本推动下，灵活 IT 允许暂时超调，但沟通必须把超调说成暂时，否则锚漂。严格 IT 在巧合破裂时牺牲过大缺口，往往不是最优——上一课的 \\(\\lambda_y\\) 正是灵活的理由。责任机制（解释偏离、任期）用来缓解权变诱惑：复苏后不肯「还」通胀欠账。</p><p>双重使命（通胀与就业）在灵活 IT 里已经在损失中，不必另立第二个数字锚。把就业写成与 \\(\\pi^*\\) 对称的长期目标，会与自然率冲突：长期 \\(u\\) 回 \\(u^*\\)，不能钉一个任意的就业水平。沟通上同时报缺口，是识别需求与成本冲击，不是放弃 \\(\\pi^*\\) 作为名义锚。</p><p>开放经济还要声明汇率是否进入损失。CIP 实证仍在 <code>/quant/irp</code>。本课不把 IT 写成不可能三角的第四顶点。</p><p><span class="marginnote">「看 infl 预测加息」容易被误读成滞后。预测目标是前瞻的：今天的 \\(i\\) 为了未来的 \\(\\pi\\) 路径。滞后的是数据，不是目标。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不评估某国 IT 的基点成败，不把目标写成政治口号。操作框架（走廊、地板、IOR）下一课才进入资产负债表。ZLB 上 IT 要靠路径承诺才能继续锚住 \\(\\mathbb{E}\\pi\\)，那是非常规课。量化栏没有宏观锚。</p><p>目标是 CPI 还是 PCE、是否剔食品能源，是价格指数课留下的篮子问题，会改沟通，不改「要有一个 \\(\\pi^*\\)」。点目标与区间：区间过宽等于锚软，过窄等于假装没有成本推动。灵活 IT 用损失权重处理这件事，而不是靠把区间印得很宽来假装没有权衡。</p><p>后课默认：名义锚默认是灵活通胀目标，\\(\\pi^*\\) 公开，短期权衡不取消中期钉住。下一课：政策利率如何在准备金市场上被实施。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>最优课给出目标制条件；IT 是它的公开制度。</li><li>灵活 IT：中期钉 \\(\\pi^*\\)，短期允许缺口权衡。</li><li>预测目标把前瞻部分交给可检验的路径。</li><li>盯的是 \\(\\pi\\)，不是外生 \\(M\\)；长期中性仍在。</li><li>出处：Svensson 的通胀目标制与预测目标；Bernanke 对 IT 框架的论述。</li></ul>',17))])}const A=o(h,[["render",c]]);export{f as __pageData,A as default};
